import { CLI_COMMAND_NAME as CLI } from "../../internal/distribution.js";
export const SLACK_SETUP_PHASES = [
    {
        id: "generate",
        actor: "agent",
        title: "Generate channel + manifests",
        steps: [
            `${CLI} slack init --manual --dir . --name My Agent`,
            "Installs the Slack app when Slack CLI is logged in. Otherwise next asks the user to install it.",
            "Manifests default to Socket Mode (no public Request URL).",
        ],
    },
    {
        id: "createApps",
        actor: "human",
        title: "Create two Slack apps from manifests",
        steps: [
            "Preferred: Slack CLI at ~/.slack/bin/slack. slack login --no-prompt, then slack app install --environment local --team <T> --force",
            "Prod: SLACK_ENV=deployed slack app install --environment deployed --team <T> --force",
            "Do not slack deploy; Agent SDK serve owns Socket Mode",
            "Fallback: https://api.slack.com/apps -> Create New App from a manifest",
            "Paste .slack/manifest.dev.json, then manifest.prod.json",
        ],
    },
    {
        id: "install",
        actor: "human",
        title: "Install + mint App-Level Token",
        steps: [
            "Slack CLI install leaves tokens in that process only. Copy xoxb from OAuth & Permissions at https://api.slack.com/apps/<appId>",
            "App-Level Tokens: create token with connections:write; copy xapp-...",
            "If Slack CLI wrote SLACK_* to .env, copy them into .env.local using env.example names",
        ],
    },
    {
        id: "env",
        actor: "agent",
        title: "Wire environment",
        steps: [
            "Write per-agent tokens into .env.local (see .agent-serve/slack/env.example)",
            "Multi-agent: <PREFIX>_SLACK_BOT_TOKEN + <PREFIX>_SLACK_APP_TOKEN",
            "Single agent: SLACK_BOT_TOKEN + SLACK_APP_TOKEN (--no-prefix)",
            `${CLI} slack doctor --prefix <PREFIX>`,
        ],
    },
    {
        id: "serve",
        actor: "agent",
        title: "Serve",
        steps: [`${CLI} serve --dir . --dev`, "Confirm log: [bdk/slack] Socket Mode connected"],
    },
    {
        id: "smoke",
        actor: "human",
        title: "Smoke test",
        steps: [
            "Invite the bot to a channel",
            "@mention it or DM it",
            "Confirm logs: inbound → session start → reply delivered",
            "Confirm streaming reply and rotating status",
        ],
    },
];
/** Seed `.agent-serve/slack/setup-status.json` after `slack init --manual`. */
export function initialSlackSetupStatus(options) {
    const completed = SLACK_SETUP_PHASES[0]?.id;
    return {
        updatedAt: new Date().toISOString(),
        envPrefix: options.envPrefix ?? null,
        envKeys: options.envKeys,
        phases: Object.fromEntries(SLACK_SETUP_PHASES.map((phase) => [phase.id, phase.id === completed])),
    };
}
export function formatSlackSetupGuide() {
    const lines = [
        `${CLI} — Slack setup`,
        "",
        "Dedicated Slack app (Socket Mode) via the dashboard wizard:",
        `  ${CLI} slack create --dir .`,
        "  Finish Slack consent and the bot name there. The CLI writes",
        "  tokens into .env.local.",
        "",
        "Manual Slack app: `slack init --manual` (Slack CLI, or paste at api.slack.com).",
        "Goal: importable dev + prod Slack apps over Socket Mode (no public URL).",
        "App-Level Token (xapp-...) + Bot Token (xoxb-...) required.",
        "",
    ];
    for (const [index, phase] of SLACK_SETUP_PHASES.entries()) {
        lines.push(`## Phase ${index} — ${phase.title} (${phase.actor})`);
        for (const step of phase.steps) {
            lines.push(`  - ${step}`);
        }
        lines.push("");
    }
    lines.push("Status file: .agent-serve/slack/setup-status.json");
    lines.push("Skill (Cursor): packages/agent-serve/skills/setup-slack/SKILL.md");
    lines.push("");
    return lines.join("\n");
}
